(function(root){'use strict';
const copy=v=>JSON.parse(JSON.stringify(v));
function leaves(value,path=[],out=[]){if(typeof value==='number'&&Number.isFinite(value))out.push({key:path.join('.'),path,value});else if(value&&typeof value==='object')for(const[k,v]of Object.entries(value))if(!['name','source'].includes(k))leaves(v,[...path,k],out);return out;}
function set(input,path,value){const out=copy(input);let p=out;for(const key of path.slice(0,-1))p=p[key];p[path.at(-1)]=value;return out;}
function numeric(results){return Object.fromEntries(Object.entries(results).filter(([key,v])=>typeof v==='number'&&Number.isFinite(v)&&!/residual/i.test(key)));}
function sensitivity(evaluate,inputs,metric,fraction=.01){if(!Number.isFinite(fraction)||fraction<=0||fraction>.25)throw Error('Choose a perturbation above zero and at most 25%.');const base=evaluate(inputs).results[metric];if(!Number.isFinite(base))throw Error('Choose a finite numerical result.');const rank=r=>r.elasticity===null?-Infinity:Math.abs(r.elasticity);return leaves(inputs).map(field=>{const delta=Math.abs(field.value)*fraction||fraction;try{const low=evaluate(set(inputs,field.path,field.value-delta)).results[metric],high=evaluate(set(inputs,field.path,field.value+delta)).results[metric];if(!Number.isFinite(low)||!Number.isFinite(high))throw Error('Result not finite.');const slope=(high-low)/(2*delta);return {key:field.key,baseline:field.value,step:delta,slope,elasticity:base!==0?slope*field.value/base:null,low,high,error:null};}catch(error){return {key:field.key,baseline:field.value,step:delta,slope:null,elasticity:null,error:error.message};}}).sort((a,b)=>rank(b)-rank(a));}
async function heatmap(evaluate,inputs,metric,x,y,{size=20,cancel=()=>false,yieldTask=()=>new Promise(r=>setTimeout(r,0))}={}){if(!Number.isInteger(size)||size<2||size>30||x.path.join('.')===y.path.join('.')||![x.min,x.max,y.min,y.max].every(Number.isFinite)||x.min>=x.max||y.min>=y.max)throw Error('Choose two different inputs with finite increasing ranges.');const rows=[];for(let j=0;j<size;j++){if(cancel())throw Error('Analysis cancelled.');for(let i=0;i<size;i++){const a=x.min+(x.max-x.min)*i/(size-1),b=y.min+(y.max-y.min)*j/(size-1);try{const value=evaluate(set(set(inputs,x.path,a),y.path,b)).results[metric];if(!Number.isFinite(value))throw Error('Result not finite.');rows.push({x:a,y:b,value,error:null});}catch(e){rows.push({x:a,y:b,value:null,error:e.message});}}await yieldTask();}return rows;}
function curves(a,b){const pairs=[];for(const ca of a.curves||[]){const cb=b.curves?.find(q=>q.id===ca.id);if(!cb||ca.xLabel!==cb.xLabel||ca.yLabel!==cb.yLabel)continue;const series=[];for(const [index,scenario]of [ca,cb].entries())for(const s of scenario.series||[]){const points=s.points.filter(p=>Number.isFinite(p.x)&&Number.isFinite(p.y));if(points.length)series.push({name:(index?'B · ':'A · ')+s.name,dashed:!!index,points});}if(series.length)pairs.push({...ca,series});}return pairs;}
root.MT_ANALYSIS={copy,leaves,set,numeric,sensitivity,heatmap,curves};
})(typeof window==='undefined'?globalThis:window);
